import { MeshPhysicalNodeMaterial, MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, length, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitivesLib from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, BoxGeometry, CircleGeometry, Mesh, PointLight, Box3, Vector3 } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-features-thumbnail-card';

  const CARD_W = 1.8;
  const CARD_H = 2.2;
  const CARD_D = 0.08;

  const disposables = [];
  const timelines = [];
  const primitiveHandles = [];

  // --- machined-metal card plate ---
  const plateGeo = new BoxGeometry(CARD_W, CARD_H, CARD_D);
  const plateMat = new MeshPhysicalNodeMaterial({
    color: colors.ink,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.z = -CARD_D * 0.5;
  root.add(plate);
  disposables.push(plateGeo, plateMat);

  // --- caption strip (surface color) at bottom of card ---
  const stripH = 0.42;
  const stripGeo = new BoxGeometry(CARD_W, stripH, CARD_D + 0.01);
  const stripMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.6,
    metalness: 0.3,
  });
  const strip = new Mesh(stripGeo, stripMat);
  strip.position.set(0, -CARD_H / 2 + stripH / 2, -CARD_D * 0.4);
  root.add(strip);
  disposables.push(stripGeo, stripMat);

  // --- accent line separating strip from image area ---
  const lineGeo = new BoxGeometry(CARD_W, 0.02, CARD_D + 0.02);
  const lineMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    emissive: colors.accent,
    emissiveIntensity: 1.2,
    roughness: 0.4,
    metalness: 0.2,
  });
  const line = new Mesh(lineGeo, lineMat);
  line.position.set(0, -CARD_H / 2 + stripH, -CARD_D * 0.35);
  root.add(line);
  disposables.push(lineGeo, lineMat);

  // --- contact shadow plane beneath card ---
  const shadowGeo = new CircleGeometry(CARD_W * 0.75, 32);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const dist = length(uv().sub(vec2(0.5, 0.5)));
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = smoothstep(0.5, 0.0, dist).mul(0.5);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -CARD_H / 2 - 0.05, 0.3);
  root.add(shadow);
  disposables.push(shadowGeo, shadowMat);

  // --- accent rim light (node-local, behind card) ---
  const rimLight = new PointLight(colors.accent, 0.9, 4);
  rimLight.position.set(-0.6, 0.4, -1.0);
  root.add(rimLight);

  // --- hero mesh content (gear glb) filling upper image area ---
  const meshGroup = new Group();
  meshGroup.position.set(0, stripH / 2 + 0.05, 0.05);
  root.add(meshGroup);

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      const scene = gltf.scene;
      const box = new Box3().setFromObject(scene);
      const size = new Vector3();
      box.getSize(size);
      const targetH = CARD_H - stripH - 0.3;
      const scaleFactor = size.y > 0 ? (targetH / size.y) : 1;
      scene.scale.setScalar(scaleFactor);

      const box2 = new Box3().setFromObject(scene);
      const center = new Vector3();
      box2.getCenter(center);
      scene.position.sub(center);

      meshGroup.add(scene);

      gsap.fromTo(
        meshGroup.scale,
        { x: 0.001, y: 0.001, z: 0.001 },
        { x: 1, y: 1, z: 1, duration: 0.7, ease: 'power2.out' }
      );
    }).catch(() => {});
  }

  // --- weighted-settle entrance ---
  root.scale.setScalar(0.96);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  // --- cinematic primitives ---
  const specPrimitives = config.cinematicPrimitives ?? [];
  for (const p of specPrimitives) {
    if (typeof ctx.primitives?.[p.name] === 'function') {
      const handle = ctx.primitives[p.name](root, p.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // --- hover: rise-in subtle 0.15 units ---
  const baseY = root.position.y;
  let hoverTl = null;

  function onPointerEnter() {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: '+=0.15',
      duration: 0.5,
      ease: 'power2.out',
    });
    timelines.push(hoverTl);
  }

  function onPointerLeave() {
    hoverTl?.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, {
      y: baseY,
      duration: 0.5,
      ease: 'power2.out',
    });
    timelines.push(hoverTl);
  }

  function onClick() {
    const pressTl = gsap.timeline();
    pressTl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' })
      .to(root.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
    timelines.push(pressTl);
    ctx.emit('hub-features.select', { id: 'hub-features-thumbnail-card' });
  }

  root.userData.handlers = {
    pointerenter: onPointerEnter,
    pointerleave: onPointerLeave,
    click: onClick,
  };

  root.userData.cleanup = function cleanup() {
    for (const tl of timelines) {
      tl?.kill?.();
    }
    entranceTl?.kill?.();
    hoverTl?.kill?.();

    for (const handle of primitiveHandles) {
      handle?.cleanup?.();
    }

    for (const res of disposables) {
      res?.dispose?.();
    }

    meshGroup.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose?.();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose?.());
        } else {
          obj.material.dispose?.();
        }
      }
    });

    rimLight.dispose?.();
  };

  return root;
}
